#!/usr/bin/env python3
# Keeps the hand-verified checksums (#859) from outliving the Kotlin version they were verified for.
#
# A checksum Gradle wrote ("Generated by Gradle") is regenerated by every host, so it never goes
# stale by itself. A hand-verified one (the Binaryen and Node archives the Kotlin plugin downloads
# outside dependency resolution, #850) is not regenerated, and nothing else retires it when its
# version is bumped. The plugin picks those versions from its own defaults, which change with Kotlin.
# scripts/gradle/hand-verified-pins.txt records the Kotlin version and the tool versions the
# hand-verified checksums were checked against, so a Kotlin bump fails this check until someone
# re-verifies the new defaults and updates the pins.
#
#   python3 -I scripts/gradle/check-hand-verified.py gradle/verification-metadata.xml gradle/libs.versions.toml
#       fails if the pins name another Kotlin version, or a hand-verified checksum is for a version
#       the pins do not list
#   python3 -I scripts/gradle/check-hand-verified.py --prune gradle/verification-metadata.xml gradle/libs.versions.toml
#       also removes the stale hand-verified checksums (update-verification.sh --prune runs this)
import os
import re
import sys
import xml.etree.ElementTree as ET

NS = "https://schema.gradle.org/dependency-verification"
XSI = "http://www.w3.org/2001/XMLSchema-instance"
GENERATED = "Generated by Gradle"
HERE = os.path.dirname(os.path.abspath(__file__))
PINS = os.path.join(HERE, "hand-verified-pins.txt")


def kotlin_version(toml_path):
    """The `kotlin` entry of the [versions] table in gradle/libs.versions.toml."""
    section = None
    with open(toml_path, encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if stripped.startswith("["):
                section = stripped
                continue
            match = re.match(r'kotlin\s*=\s*"([^"]+)"', stripped)
            if section == "[versions]" and match:
                return match.group(1)
    raise ValueError(f"no kotlin version in the [versions] table of {toml_path}")


def read_pins(path=PINS):
    """(kotlin version, {"group:name": {version, ...}}) from the pins file."""
    kotlin = None
    tools = {}
    with open(path, encoding="utf-8") as f:
        for raw in f:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            key, value = line.split(None, 1)
            if key == "kotlin":
                kotlin = value
            else:
                tools.setdefault(key, set()).add(value)
    if kotlin is None:
        raise ValueError(f"{path} names no kotlin version")
    return kotlin, tools


def hand_verified_stale(root, tools):
    """(component element, artifact element, checksum element, 'group:name version') for each stale one."""
    stale = []
    components = root.find(f"{{{NS}}}components")
    if components is None:
        return stale
    for component in components:
        key = f"{component.get('group')}:{component.get('name')}"
        version = component.get("version")
        for artifact in component:
            for checksum in artifact:
                if checksum.get("origin") == GENERATED:
                    continue
                if version not in tools.get(key, set()):
                    stale.append((component, artifact, checksum, f"{key} {version} ({artifact.get('name')})"))
    return stale


def check(metadata_path, toml_path, prune=False, pins_path=PINS):
    kotlin_pin, tools = read_pins(pins_path)
    kotlin_now = kotlin_version(toml_path)
    problems = []
    if kotlin_pin != kotlin_now:
        problems.append(
            f"hand-verified checksums were checked against Kotlin {kotlin_pin}, but libs.versions.toml "
            f"says {kotlin_now}: re-verify the plugin's Binaryen and Node defaults on each host, then "
            "update scripts/gradle/hand-verified-pins.txt"
        )

    ET.register_namespace("", NS)
    ET.register_namespace("xsi", XSI)
    tree = ET.parse(metadata_path)
    root = tree.getroot()
    stale = hand_verified_stale(root, tools)
    if prune and stale:
        # Removing them is the fix, so they are reported as pruned rather than as problems.
        for component, artifact, checksum, description in stale:
            artifact.remove(checksum)
            print(f"pruned stale hand-verified checksum: {description}")
            if len(artifact) == 0:
                component.remove(artifact)
        components = root.find(f"{{{NS}}}components")
        for component in list(components):
            if len(component) == 0:
                components.remove(component)
        tree.write(metadata_path, encoding="UTF-8", xml_declaration=True)
    elif stale:
        for *_, description in stale:
            problems.append(f"hand-verified checksum for a version the pins do not list: {description}")

    for problem in problems:
        print(f"::error::{problem}")
    return 1 if problems else 0


def main(argv):
    prune = "--prune" in argv
    args = [a for a in argv if a != "--prune"]
    if len(args) != 2:
        sys.exit("usage: check-hand-verified.py [--prune] <verification-metadata.xml> <libs.versions.toml>")
    return check(args[0], args[1], prune=prune)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
